(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10+Math.sin((x+y)*0.01+t*0.5)*8;
  const wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10+Math.cos((x-y)*0.012-t*0.4)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.5],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.4],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.6],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*40,0.11,2.1,0.8],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*50,0.05,1.8,0.35]
  ];
  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp,feed]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*feed;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*(1-feed);
    hS+=Math.sin(d*f*1.3-t*sp*0.8+3)*0.5;
  }
  const act=aS/8,inh=iS/8,harm=hS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*1.8)*Math.cos(sy*0.06-t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2+t*0.8)*0.2;
  const c2x=240+Math.sin(t*0.3)*120,c2y=120+Math.cos(t*0.4)*80;
  const d2=Math.sqrt((sx-c2x)**2+(sy-c2y)**2),a2=Math.atan2(sy-c2y,sx-c2x);
  const spiral2=Math.sin(d2*0.06+a2*5-t*1.8)*0.3;
  const pulse=1+Math.sin(t*0.7)*0.08;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2+harm*0.4)*2.0*pulse);
  const cellX=Math.sin(sx*0.15+t*0.2)*Math.sin(sy*0.12-t*0.15);
  const cellY=Math.cos(sx*0.12-t*0.18)*Math.cos(sy*0.14+t*0.22);
  const cell=Math.tanh((cellX+cellY+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const detail=Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.2-sy*0.3-t*2.5)*0.15;
  const blend=reaction*0.6+cell*0.25+detail*0.15;
  const v=blend*0.5+0.5;
  const pal=[[5,10,48],[15,35,95],[22,80,125],[32,148,138],[110,188,105],[215,198,58],[222,135,48],[188,68,52],[138,32,62],[68,14,58],[28,8,48],[5,10,48]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.75?1.12:1.0;
  const glow=Math.max(0,reaction-0.5)*0.3;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*80)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*40)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*20)|0];
}
